import {SpatialView} from '../../foundation/spatial.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={
 en:{structure:'Lab Structure',overview:'Overview',knowledge:'Knowledge Links',environment:'Environment',initial:'Initial State',taskGraph:'Task Graph',tools:'Tools & Actions',signals:'Expected Signals',validation:'Validation',safety:'Safety & Reset',result:'Result Schema',completion:'Completion Criteria',addTask:'Add Task',connect:'Connect',branch:'Add Branch',preflight:'Preflight',handoff:'Prepare Handoff',revise:'New Revision',selected:'Selected task / branch',save:'Save change',source:'From',target:'To',edgeType:'Edge',condition:'Condition',spatial:'Non-linear Task Graph',structured:'Shared Structured owner'},
 ar:{structure:'بنية المختبر',overview:'نظرة عامة',knowledge:'روابط المعرفة',environment:'البيئة',initial:'الحالة الأولية',taskGraph:'مخطط المهام',tools:'الأدوات والإجراءات',signals:'الإشارات المتوقعة',validation:'التحقق',safety:'السلامة وإعادة الضبط',result:'مخطط النتيجة',completion:'معايير الإكمال',addTask:'إضافة مهمة',connect:'ربط',branch:'إضافة فرع',preflight:'فحص مسبق',handoff:'تحضير التسليم',revise:'مراجعة جديدة',selected:'المهمة / الفرع المحدد',save:'حفظ التغيير',source:'من',target:'إلى',edgeType:'الحافة',condition:'الشرط',spatial:'مخطط مهام غير خطي',structured:'مالك Structured المشترك'}
};
function style(root){if(root.querySelector(':scope > style[data-s11-lab-style]'))return;root.insertAdjacentHTML('afterbegin',`<style data-s11-lab-style>
.s11-lab{display:grid;grid-template-columns:minmax(190px,240px) minmax(440px,1fr) minmax(250px,320px);grid-template-rows:auto minmax(500px,1fr) auto;min-height:700px;background:var(--bg,#101417);color:var(--text,#eef2f3);border:1px solid var(--line,#30383d);border-radius:12px;overflow:hidden;font:13px/1.45 system-ui,sans-serif}.s11-lab-top{grid-column:1/-1;display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:10px 12px;background:var(--panel,#171d21);border-bottom:1px solid var(--line,#30383d)}.s11-lab-top .identity{margin-inline-end:auto}.s11-lab button{border:1px solid var(--line2,#44515a);background:var(--button,#242c31);color:inherit;border-radius:7px;padding:6px 9px;cursor:pointer}.s11-lab button:disabled{opacity:.42;cursor:not-allowed}.s11-lab-left,.s11-lab-right{padding:10px;background:var(--panel,#171d21);overflow:auto}.s11-lab-left{border-inline-end:1px solid var(--line,#30383d)}.s11-lab-right{border-inline-start:1px solid var(--line,#30383d)}.s11-lab-left h3,.s11-lab-right h3{font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--text2,#b8c1c6)}.s11-lab-tree{display:grid;gap:3px}.s11-lab-tree button{width:100%;text-align:start;background:transparent;border:0;padding:6px 7px}.s11-lab-tree button:hover,.s11-lab-tree button[data-selected=true]{background:var(--hover,#26323a)}.s11-lab-center{min-width:0;display:grid;grid-template-rows:auto minmax(400px,1fr)}.s11-lab-tools{display:flex;gap:6px;align-items:center;flex-wrap:wrap;padding:10px 12px;border-bottom:1px solid var(--line,#30383d)}.s11-lab-tools select{background:var(--field,#11171b);color:inherit;border:1px solid var(--line2,#44515a);border-radius:6px;padding:6px}.s11-lab-spatial{min-height:410px;position:relative}.s11-lab-spatial>.spatial-shell{height:100%;min-height:410px}.s11-lab-context{display:grid;gap:8px}.s11-lab-context label{display:grid;gap:4px;color:var(--text2,#b8c1c6)}.s11-lab-context input,.s11-lab-context textarea,.s11-lab-context select{width:100%;box-sizing:border-box;border:1px solid var(--line2,#44515a);background:var(--field,#11171b);color:inherit;border-radius:6px;padding:7px}.s11-lab-bottom{grid-column:1/-1;display:flex;gap:14px;align-items:center;flex-wrap:wrap;padding:8px 12px;background:var(--panel,#171d21);border-top:1px solid var(--line,#30383d);color:var(--text2,#b8c1c6)}.s11-lab-state{display:inline-flex;padding:2px 7px;border:1px solid var(--line2,#44515a);border-radius:999px}.s11-lab-status[data-state=blocked]{color:#ffbf69}.s11-lab-status[data-state=ok]{color:#9ee6a8}.s11-lab-shared{margin-inline-start:auto;font-size:11px}bdi{unicode-bidi:isolate}@media(max-width:1120px){.s11-lab{grid-template-columns:190px minmax(360px,1fr);grid-template-rows:auto minmax(500px,1fr) auto auto}.s11-lab-right{grid-column:1/-1;border-inline-start:0;border-top:1px solid var(--line,#30383d);max-height:280px}.s11-lab-bottom{grid-row:4}}@media(max-width:820px){.s11-lab{grid-template-columns:1fr}.s11-lab-left{display:none}.s11-lab-center,.s11-lab-right,.s11-lab-bottom{grid-column:1}.s11-lab-right{max-height:none}}
</style>`)}
function graph(projection){const tasks=projection.tasks,edges=projection.edges,nodes=tasks.map((task,index)=>{const incoming=edges.filter(e=>e.to===task.id).length,outgoing=edges.filter(e=>e.from===task.id).length;return {id:`task:${task.id}`,label:task.title||task.id,type:task.nodeType||'task',x:90+(index%4)*245,y:90+Math.floor(index/4)*190+(incoming>1?35:0)+(outgoing>1?15:0)}}),relations=edges.map(edge=>({id:`edge:${edge.id}`,source:`task:${edge.from}`,target:`task:${edge.to}`,type:'depends',direction:'directed',label:edge.label||edge.condition||edge.type,kind:'representation'}));return {nodes,edges:relations}}
function nextTaskId(tasks){let n=tasks.length+1,id=`TASK-${n}`,ids=new Set(tasks.map(x=>x.id));while(ids.has(id))id=`TASK-${++n}`;return id}
export function renderLabsSurface(root,composition,{dir='rtl',locale=dir==='rtl'?'ar':'en',toolContext={tools:{},environmentBinding:{capabilities:[]}}}={}){
  if(!root||!composition)throw Error('LABS_PRESENTATION_INPUT_REQUIRED');const t=labels[locale]||labels.en;root.dir=dir;root.dataset.surface='labs';root.dataset.workspaceInteraction='authoring';let spatial=null,statusText='';
  const act=(id,payload={})=>{const r=composition.bus.execute(id,payload);if(r?.ok===false&&r.reason)statusText=r.reason;draw();return r};
  const draw=()=>{
    const projection=composition.domain.graphProjection(),pre=composition.domain.preflight(toolContext),selected=composition.domain.selectionContext(),published=projection.lifecycle==='PUBLISHED',handoffAvailability=composition.bus.availability('labs.handoff',toolContext),handoffEnabled=handoffAvailability===true||handoffAvailability?.enabled===true,tasks=projection.tasks,edges=projection.edges,taskOptions=tasks.map(x=>`<option value="${esc(x.id)}">${esc(x.title||x.id)}</option>`).join('');
    root.innerHTML=`<section class="s11-lab" aria-label="Lab authoring Studio"><header class="s11-lab-top"><div class="identity"><strong>${esc(projection.title||'Untitled Lab')}</strong> · <bdi dir="ltr">${esc(projection.identity.id)}@${esc(projection.identity.revision)}</bdi> <span class="s11-lab-state">${esc(projection.lifecycle)}</span></div><button data-action="preflight">${t.preflight}</button><button data-action="revise">${t.revise}</button><button data-action="handoff" ${handoffEnabled?'':'disabled'}>${t.handoff}</button></header><aside class="s11-lab-left"><h3>${t.structure}</h3><div class="s11-lab-tree"><div>${t.overview}</div><div>${t.knowledge}</div><div><span>${t.environment}</span> · <bdi dir="ltr">${(projection.environment.capabilities||[]).map(esc).join(', ')||'—'}</bdi></div><div>${t.initial}</div><strong>${t.taskGraph} (${tasks.length})</strong>${tasks.map(task=>`<button data-select-task="${esc(task.id)}" data-selected="${selected.id===task.id}">${esc(task.title||task.id)} <bdi dir="ltr">${esc(task.id)}</bdi></button>`).join('')||'<span>—</span>'}<strong>Branches (${edges.filter(e=>['branch','conditional','optional'].includes(e.type)).length})</strong>${edges.filter(e=>['branch','conditional','optional'].includes(e.type)).map(edge=>`<button data-select-edge="${esc(edge.id)}" data-selected="${selected.id===edge.id}">${esc(edge.label||edge.condition||edge.type)} · <bdi dir="ltr">${esc(edge.from)}→${esc(edge.to)}</bdi></button>`).join('')}<div>${t.tools} (${projection.requiredTools.length})</div><div>${t.signals}</div><div>${t.validation}</div><div>${t.safety}</div><div>${t.result}</div><div>${t.completion}</div></div></aside><main class="s11-lab-center"><div class="s11-lab-tools"><strong>${t.spatial}</strong><button data-create-task ${published?'disabled':''}>${t.addTask}</button><label>${t.source}<select data-edge-from ${published?'disabled':''}>${taskOptions}</select></label><label>${t.target}<select data-edge-to ${published?'disabled':''}>${taskOptions}</select></label><label>${t.edgeType}<select data-edge-type ${published?'disabled':''}><option value="depends">depends</option><option value="branch">branch</option><option value="conditional">conditional</option><option value="optional">optional</option></select></label><input data-edge-condition placeholder="${esc(t.condition)}" ${published?'disabled':''}><button data-connect ${published?'disabled':''}>${t.connect}</button></div><div class="s11-lab-spatial" data-spatial-host aria-label="Shared Spatial Lab Task Graph"></div></main><aside class="s11-lab-right"><h3>${t.selected}</h3>${selected.kind==='task'?`<form class="s11-lab-context" data-task-form><label>ID <bdi dir="ltr">${esc(selected.id)}</bdi></label><label>Title<input name="title" value="${esc(selected.object?.title||'')}" ${selected.editable?'':'disabled'}></label><label>Node type<select name="nodeType" ${selected.editable?'':'disabled'}>${['objective','action','check','interpret','evidence'].map(x=>`<option value="${x}" ${selected.object?.nodeType===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Validation<input name="validation" value="${esc(selected.object?.validation||'')}" ${selected.editable?'':'disabled'}></label><label>Expected signal<textarea name="expectedSignal" ${selected.editable?'':'disabled'}>${esc(selected.object?.expectedSignal||'')}</textarea></label><button type="submit" ${selected.editable?'':'disabled'}>${t.save}</button></form>`:selected.kind==='branch'?`<form class="s11-lab-context" data-edge-form><label>ID <bdi dir="ltr">${esc(selected.id)}</bdi></label><label>Type<select name="type" ${selected.editable?'':'disabled'}>${['branch','conditional','optional','depends'].map(x=>`<option value="${x}" ${selected.object?.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label>${t.condition}<textarea name="condition" ${selected.editable?'':'disabled'}>${esc(selected.object?.condition||selected.object?.label||'')}</textarea></label><button type="submit" ${selected.editable?'':'disabled'}>${t.save}</button></form>`:`<p>${esc(selected.title||projection.title)}</p>`}<div class="s11-lab-shared"><span>${t.structured}</span><br><bdi dir="ltr">${esc(composition.shared.structuredHost?.owner||composition.shared.structuredHost?.descriptor?.()?.owner||'BOUND_SHARED_OWNER')}</bdi></div></aside><footer class="s11-lab-bottom"><span class="s11-lab-status" data-state="${pre.status==='READY'?'ok':'blocked'}" role="status" tabindex="-1">${esc(statusText||`Preflight ${pre.status}`)}</span><span dir="ltr">Graph: <bdi dir="ltr">${tasks.length} tasks / ${edges.length} edges / nonLinear=${composition.domain.validate().graph.nonLinear}</bdi></span><span dir="ltr">Simulation explicit: <bdi dir="ltr">${pre.simulationExplicit}</bdi></span><span dir="ltr">Run created: <bdi dir="ltr">false</bdi></span></footer></section>`;
    style(root);const g=graph(projection),host=root.querySelector('[data-spatial-host]');spatial=new SpatialView(host,g.nodes,g.edges,{select:ids=>{const raw=ids.at(-1);if(!raw)return;const [kind,id]=raw.split(':');composition.domain.select({kind:kind==='task'?'task':'edge',id});draw()},edgeSelect:id=>{if(!id)return;composition.domain.select({kind:'edge',id:id.replace(/^edge:/,'')});draw()},open:id=>{composition.domain.select({kind:'task',id:id.replace(/^task:/,'')});draw()}});spatial.setActiveMode(published?'review':'author');
    root.querySelector('[data-action="preflight"]').onclick=()=>{const r=composition.bus.execute('labs.preflight',toolContext);statusText=`Preflight ${r.status}`;draw()};root.querySelector('[data-action="handoff"]')?.addEventListener('click',()=>{const r=composition.bus.execute('labs.handoff',toolContext);statusText=r.ok?(locale==='ar'?'تم تجميد إدخال المختبر؛ لم يتم إنشاء Run.':'Lab input frozen; no Run created.'):(r.code||'Blocked');draw()});root.querySelector('[data-action="revise"]').onclick=()=>{const r=composition.bus.execute('labs.revise',{expectedVersion:composition.domain.version});statusText=r?.snapshot?(locale==='ar'?'تم إنشاء مراجعة جديدة مع حفظ المصدر.':'Successor revision created; source preserved.'):(r.reason||'');draw()};
    root.querySelector('[data-create-task]')?.addEventListener('click',()=>{const id=nextTaskId(tasks);act('labs.author',{op:'addTask',task:{id,title:`Task ${tasks.length+1}`,nodeType:'action',validation:'event',expectedSignal:'expected signal'}})});root.querySelector('[data-connect]')?.addEventListener('click',()=>{const from=root.querySelector('[data-edge-from]').value,to=root.querySelector('[data-edge-to]').value,type=root.querySelector('[data-edge-type]').value,condition=root.querySelector('[data-edge-condition]').value;if(!from||!to){statusText='Select source and target.';draw();return}act('labs.author',{op:'connect',edge:{from,to,type,condition,label:condition}})});
    root.querySelectorAll('[data-select-task]').forEach(button=>button.onclick=()=>{composition.domain.select({kind:'task',id:button.dataset.selectTask});draw()});root.querySelectorAll('[data-select-edge]').forEach(button=>button.onclick=()=>{composition.domain.select({kind:'edge',id:button.dataset.selectEdge});draw()});const taskForm=root.querySelector('[data-task-form]');if(taskForm)taskForm.onsubmit=e=>{e.preventDefault();const data=new FormData(taskForm),ctx=composition.domain.selectionContext();act('labs.author',{op:'updateTask',taskId:ctx.id,patch:{title:String(data.get('title')||''),nodeType:String(data.get('nodeType')||'action'),validation:String(data.get('validation')||''),expectedSignal:String(data.get('expectedSignal')||'')}})};const edgeForm=root.querySelector('[data-edge-form]');if(edgeForm)edgeForm.onsubmit=e=>{e.preventDefault();const data=new FormData(edgeForm),ctx=composition.domain.selectionContext();act('labs.author',{op:'updateEdge',edgeId:ctx.id,patch:{type:String(data.get('type')||'depends'),condition:String(data.get('condition')||''),label:String(data.get('condition')||'')}})};
  };
  draw();return {refresh:draw,focus:()=>root.querySelector('button')?.focus(),get spatial(){return spatial},descriptor:()=>({surface:'labs',owner:'W03LabDomain',spatialOwner:'SpatialView',structuredOwner:composition.shared.structuredHost?.owner||'BOUND_SHARED_OWNER',localSpatialEngine:false,localStructuredEngine:false})};
}
